// goldenHeader is the Envoy header generated by a standalone encoder with
// Envoy's own percent-encoding rules, reused from the xfcc adapter's fixtures.
func goldenHeader(t *testing.T) string {
	t.Helper()

	data, err := os.ReadFile("../../internal/adapters/xfcc/testdata/xfcc_golden.txt")
	if err != nil {
		t.Fatalf("could not read the golden header: %v", err)
	}

	return string(data)
}

func quietLogger() *slog.Logger {
	return slog.New(slog.DiscardHandler)
}

// handler builds the card login endpoint with the given outcomes.
func handler(
	authenticateErr error,
	completeErr error,
) (*cardLogin, *bool) {
	completed := false

	return &cardLogin{
		authenticate: func(
			context.Context, *x509.Certificate,
		) (domain.CardIdentity, error) {
			if authenticateErr != nil {
				return domain.CardIdentity{}, authenticateErr
			}

			return domain.CardIdentity{}, nil
		},
		complete: func(string, domain.CardIdentity) error {
			completed = true

			return completeErr
		},
		callback: func(_ context.Context, requestID string) string {
			return "https://idp.example.se/authorize/callback?id=" + requestID
		},
		logger: quietLogger(),
	}, &completed
}

func get(t *testing.T, login http.Handler, target string, header string) *http.Response {
	t.Helper()

	request := httptest.NewRequestWithContext(
		context.Background(), http.MethodGet, target, nil)
	if header != "" {
		request.Header.Set(xfccHeader, header)
	}

	recorder := httptest.NewRecorder()
	login.ServeHTTP(recorder, request)

	return recorder.Result()
}

func TestCardLoginRedirectsBackToTheProviderOnSuccess(t *testing.T) {
	t.Parallel()

	login, completed := handler(nil, nil)

	response := get(t, login, "/login?id=request-1", goldenHeader(t))
	defer func() { _ = response.Body.Close() }()

	if response.StatusCode != http.StatusFound {
		t.Fatalf("status = %s, want 302", response.Status)
	}

	if location := response.Header.Get("Location"); !strings.Contains(location, "request-1") {
		t.Errorf("Location = %q", location)
	}

	if !*completed {
		t.Error("the authorization request was not completed")
	}
}

// Reaching the card listener without a certificate means Envoy is
// misconfigured or something bypassed it. The user cannot act on that, so they
// get a technical-error page and a reference, and nothing is authorised.
func TestCardLoginRefusesARequestWithoutACertificate(t *testing.T) {
	t.Parallel()

	login, completed := handler(nil, nil)

	response := get(t, login, "/login?id=request-1", "")
	defer func() { _ = response.Body.Close() }()

	if response.StatusCode != http.StatusInternalServerError {
		t.Errorf("status = %s, want 500", response.Status)
	}

	if *completed {
		t.Error("the authorization request was completed without a certificate")
	}
}

func TestCardLoginRefusesAnUnknownRequest(t *testing.T) {
	t.Parallel()

	login, _ := handler(nil, nil)

	response := get(t, login, "/login", goldenHeader(t))
	defer func() { _ = response.Body.Close() }()

	if response.StatusCode != http.StatusBadRequest {
		t.Errorf("status = %s, want 400", response.Status)
	}
}

// Each denial must reach the user as its own page, because each one is a
// different errand: fetch a new card, pick the other certificate, wait, or call
// the service desk. One generic failure would leave everyone calling.
func TestCardLoginShowsTheRightPageForEachDenial(t *testing.T) {
	t.Parallel()

	cases := map[string]struct {
		err        error
		wantStatus int
		wantText   string
	}{
		"expired card": {
			err:        fmt.Errorf("wrapped: %w", domain.ErrCertificateOutsideValidity),
			wantStatus: http.StatusForbidden,
			wantText:   "giltighetstid",
		},
		"wrong certificate on the card": {
			err:        fmt.Errorf("wrapped: %w", domain.ErrDisallowedKeyUsage),
			wantStatus: http.StatusForbidden,
			wantText:   "legitimeringscertifikat",
		},
		"assurance level too low": {
			err:        fmt.Errorf("wrapped: %w", domain.ErrAssuranceLevelTooLow),
			wantStatus: http.StatusForbidden,
			wantText:   "tillitsnivå",
		},
		"revoked card": {
			err:        fmt.Errorf("wrapped: %w", app.ErrCardRevoked),
			wantStatus: http.StatusForbidden,
			wantText:   "återkallat",
		},
		"revocation unreachable": {
			err:        fmt.Errorf("wrapped: %w", app.ErrRevocationStatusUnknown),
			wantStatus: http.StatusServiceUnavailable,
			wantText:   "otillgänglig",
		},
		"no revocation endpoints": {
			err:        fmt.Errorf("wrapped: %w", revocation.ErrNoRevocationEndpoints),
			wantStatus: http.StatusServiceUnavailable,
			wantText:   "otillgänglig",
		},
		"foreign issuer": {
			err:        fmt.Errorf("wrapped: %w", app.ErrCertificateChain),
			wantStatus: http.StatusForbidden,
			wantText:   "utgivare",
		},
		"unsuitable certificate": {
			err:        fmt.Errorf("wrapped: %w", efospki.ErrUnsuitableCertificate),
			wantStatus: http.StatusForbidden,
			wantText:   "utgivare",
		},
		"malformed identity": {
			err:        fmt.Errorf("wrapped: %w", domain.ErrInvalidPersonalIdentityNumber),
			wantStatus: http.StatusForbidden,
			wantText:   "nödvändig information",
		},
		"unexpected failure": {
			err:        errors.New("something nobody anticipated"),
			wantStatus: http.StatusInternalServerError,
			wantText:   "Tekniskt fel",
		},
	}

	for name, testCase := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			login, completed := handler(testCase.err, nil)

			response := get(t, login, "/login?id=request-1", goldenHeader(t))
			defer func() { _ = response.Body.Close() }()

			if response.StatusCode != testCase.wantStatus {
				t.Errorf("status = %s, want %d", response.Status, testCase.wantStatus)
			}

			body, err := io.ReadAll(response.Body)
			if err != nil {
				t.Fatalf("could not read the body: %v", err)
			}

			if !strings.Contains(string(body), testCase.wantText) {
				t.Errorf("the page does not mention %q", testCase.wantText)
			}

			if *completed {
				t.Error("the authorization request was completed despite a denial")
			}
		})
	}
}

// The revocation page must tell a load balancer and a user when to come back,
// and it must not say why the card was revoked — that is in the audit log, and
// whoever holds a stolen card learns nothing from the screen.
func TestTheRevocationPagesSayTheRightThings(t *testing.T) {
	t.Parallel()

	login, _ := handler(fmt.Errorf("wrapped: %w", app.ErrRevocationStatusUnknown), nil)

	response := get(t, login, "/login?id=request-1", goldenHeader(t))
	defer func() { _ = response.Body.Close() }()

	if response.Header.Get("Retry-After") == "" {
		t.Error("the unavailable page carries no Retry-After")
	}

	revoked, _ := handler(fmt.Errorf("wrapped: %w", app.ErrCardRevoked), nil)

	revokedResponse := get(t, revoked, "/login?id=request-1", goldenHeader(t))
	defer func() { _ = revokedResponse.Body.Close() }()

	body, err := io.ReadAll(revokedResponse.Body)
	if err != nil {
		t.Fatalf("could not read the body: %v", err)
	}

	for _, leak := range []string{"KeyCompromise", "keyCompromise", "2026-"} {
		if strings.Contains(string(body), leak) {
			t.Errorf("the revoked page leaks %q", leak)
		}
	}
}

// Every page must carry the reference that joins the user's screen to the audit
// record, or a service desk call cannot be resolved.
func TestEveryDenialCarriesAReference(t *testing.T) {
	t.Parallel()

	login, _ := handler(fmt.Errorf("wrapped: %w", app.ErrCardRevoked), nil)

	response := get(t, login, "/login?id=request-1", goldenHeader(t))
	defer func() { _ = response.Body.Close() }()

	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatalf("could not read the body: %v", err)
	}

	if !strings.Contains(string(body), "Referens:") {
		t.Error("the page carries no reference")
	}

	// The reference is a fingerprint prefix, so it must not be empty.
	if strings.Contains(string(body), "<code></code>") {
		t.Error("the reference is empty")
	}
}

// A page must never leak the internals of a failure. The error text is for the
// audit log, not for the browser.
func TestPagesDoNotLeakInternalErrors(t *testing.T) {
	t.Parallel()

	login, _ := handler(errors.New("x509: certificate signed by unknown authority"), nil)

	response := get(t, login, "/login?id=request-1", goldenHeader(t))
	defer func() { _ = response.Body.Close() }()

	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatalf("could not read the body: %v", err)
	}

	if strings.Contains(string(body), "x509:") {
		t.Error("the page leaks the underlying error")
	}
}

// Completing a request that the provider has since forgotten must not redirect
// anywhere: there is nothing to go back to.
func TestCardLoginHandlesAForgottenRequest(t *testing.T) {
	t.Parallel()

	login, _ := handler(nil, errors.New("unknown authorization request"))

	response := get(t, login, "/login?id=request-1", goldenHeader(t))
	defer func() { _ = response.Body.Close() }()

	if response.StatusCode != http.StatusBadRequest {
		t.Errorf("status = %s, want 400", response.Status)
	}

	if response.Header.Get("Location") != "" {
		t.Error("the response redirects despite the request being unknown")
	}
}
